        /**
         * Clear proxy data
         *
         * @param type
         */
        clearProxyData(type) {
          this.state.proxyData[type] = null;
        }
        /**
         * Send proxy request
         *
         * @param type
         * @param params
         *
         * @returns {Promise<*>}
         */
        async fetchProxyData(type = "wms", params2 = {}) {
          let response2;
          try {
            if (params2.changes) {
              Object.keys(params2.changes).forEach((c) => {
                Object.keys(params2.changes[c]).forEach((p) => {
                  this.state.proxyData[type][c][p] = params2.changes[c][p];
                });
              });
              params2 = this.state.proxyData[type];
            }
            if ("POST" !== params2.method) {
              const url2 = new URL(params2.url);
              Object.entries(params2.params).filter(([_, v]) => void 0 !== v).forEach(([p, v]) => url2.searchParams.set(p, v));
              params2.url = url2.toString();
            }
            const data = JSON.stringify({
              url: params2.url,
              params: params2.params ?? {},
              headers: params2.headers ?? {},
              method: params2.method ?? "GET"
            });
            response2 = await XHR.post({ data, contentType: "application/json", url: `${window.initConfig.proxyurl}` });
            this.state.proxyData[type] = JSON.parse(data);
          } catch (e) {
            console.warn(e);
          }
          return response2;
        }
